-- P1z reconciliation, detail
-- Read only. One row per object and aspect: matches true means the object is exactly what 0260 creates. Rows with matches false show what the database holds in actual_text.
-- Written 17-10-2026 for the partial state found on production (0260 parts a, b and c are there, parts d and e and everything after are not).
-- Project check first: the address bar must contain twwpnltizhtjxhamyoxt. Paste the whole file, press Run, paste the answer back. Nothing is written.
-- Generated by scripts/nav2_reconcile_0260.mjs: the expected values are the fingerprints of the objects that 0260 parts a to c create, computed with this same query.

with fp as (
  select object, aspect, replace(actual, 'public.', '') as actual from (
    select c.table_name::text as object, 'columns'::text as aspect,
      string_agg(c.column_name || ' / ' || c.data_type || ' / ' || c.is_nullable || ' / ' || coalesce(c.column_default, 'none') || ' / ' || coalesce(c.character_maximum_length, 0)::text || ' / ' || coalesce(c.numeric_precision, 0)::text || ' / ' || coalesce(c.numeric_scale, 0)::text, ' , ' order by c.column_name) as actual
    from information_schema.columns c where c.table_schema = 'public' and c.table_name in ('ii_risk_free_series', 'ii_risk_free_batches', 'ii_risk_free_observations', 'ii_risk_free_review_items', 'ii_risk_free_corrections', 'ii_risk_free_series_state_log') group by c.table_name
    union all
    select 'admin_users', 'columns', string_agg(c.column_name || ' / ' || c.data_type || ' / ' || c.is_nullable || ' / ' || coalesce(c.column_default, 'none'), ' , ' order by c.column_name)
    from information_schema.columns c where c.table_schema = 'public' and c.table_name = 'admin_users' and c.column_name in ('can_upload_risk_free_data', 'can_switch_risk_free_series')
    union all
    select cl.relname, 'constraints', string_agg(k.conname || ' = ' || pg_get_constraintdef(k.oid), ' , ' order by k.conname)
    from pg_constraint k join pg_class cl on cl.oid = k.conrelid join pg_namespace n on n.oid = cl.relnamespace where n.nspname = 'public' and k.contype <> 'n' and cl.relname in ('ii_risk_free_series', 'ii_risk_free_batches', 'ii_risk_free_observations', 'ii_risk_free_review_items', 'ii_risk_free_corrections', 'ii_risk_free_series_state_log') group by cl.relname
    union all
    select i.tablename, 'indexes', string_agg(i.indexname || ' = ' || i.indexdef, ' , ' order by i.indexname)
    from pg_indexes i where i.schemaname = 'public' and i.tablename in ('ii_risk_free_series', 'ii_risk_free_batches', 'ii_risk_free_observations', 'ii_risk_free_review_items', 'ii_risk_free_corrections', 'ii_risk_free_series_state_log') group by i.tablename
    union all
    select cl.relname, 'rls', cl.relrowsecurity::text
    from pg_class cl join pg_namespace n on n.oid = cl.relnamespace where n.nspname = 'public' and cl.relname in ('ii_risk_free_series', 'ii_risk_free_batches', 'ii_risk_free_observations', 'ii_risk_free_review_items', 'ii_risk_free_corrections', 'ii_risk_free_series_state_log')
    union all
    select p.tablename, 'policies', string_agg(p.policyname || ' / ' || p.cmd || ' / ' || p.roles::text || ' / ' || coalesce(p.qual, 'none') || ' / ' || coalesce(p.with_check, 'none'), ' , ' order by p.policyname)
    from pg_policies p where p.schemaname = 'public' and p.tablename in ('ii_risk_free_series', 'ii_risk_free_batches', 'ii_risk_free_observations', 'ii_risk_free_review_items', 'ii_risk_free_corrections', 'ii_risk_free_series_state_log') group by p.tablename
    union all
    select t.t, 'write_grants', coalesce((select string_agg(g.grantee || ' = ' || g.privilege_type, ' , ' order by g.grantee, g.privilege_type) from (select distinct grantee, privilege_type from information_schema.role_table_grants where table_schema = 'public' and table_name = t.t and grantee in ('anon', 'authenticated') and privilege_type in ('INSERT', 'UPDATE', 'DELETE', 'TRUNCATE')) g), 'none')
    from (values ('ii_risk_free_series'), ('ii_risk_free_batches'), ('ii_risk_free_observations'), ('ii_risk_free_review_items'), ('ii_risk_free_corrections'), ('ii_risk_free_series_state_log')) as t(t)
    union all
    select cl.relname, 'triggers', string_agg(t.tgname || ' = ' || pg_get_triggerdef(t.oid), ' , ' order by t.tgname)
    from pg_trigger t join pg_class cl on cl.oid = t.tgrelid join pg_namespace n on n.oid = cl.relnamespace where n.nspname = 'public' and not t.tgisinternal and cl.relname in ('ii_risk_free_series', 'ii_risk_free_batches', 'ii_risk_free_observations', 'ii_risk_free_review_items', 'ii_risk_free_corrections', 'ii_risk_free_series_state_log') group by cl.relname
    union all
    select pr.proname, 'function', string_agg(pg_get_function_identity_arguments(pr.oid) || ' / ' || pg_get_function_result(pr.oid) || ' / definer ' || pr.prosecdef::text || ' / ' || pr.provolatile::text || ' / ' || coalesce(array_to_string(pr.proconfig, ' '), 'none') || ' / body ' || md5(lower(regexp_replace(regexp_replace(pr.prosrc, '--[^\n]*', '', 'g'), '\s+', '', 'g'))) || ' / anon ' || has_function_privilege('anon', pr.oid, 'execute')::text || ' / authenticated ' || has_function_privilege('authenticated', pr.oid, 'execute')::text || ' / service ' || has_function_privilege('service_role', pr.oid, 'execute')::text, ' , ' order by pr.oid)
    from pg_proc pr join pg_namespace n on n.oid = pr.pronamespace where n.nspname = 'public' and pr.proname in ('is_risk_free_data_admin', 'is_risk_free_series_switch_admin', 'ii_risk_free_append_only', 'ii_risk_free_obs_guard') group by pr.proname
    union all
    select 'ii_risk_free_series', 'seed_rows', string_agg(s.series_id || ' / ' || s.series_name || ' / ' || s.role || ' / ' || s.source || ' / ' || s.attribution_text || ' / ' || s.cadence || ' / ' || s.max_staleness_days::text || ' / enabled ' || s.enabled::text || ' / ' || s.terms_review_status || ' / verified ' || coalesce(s.verified_through_date::text, 'none'), ' , ' order by s.series_id)
    from public.ii_risk_free_series s
    union all
    select a, 'absent', count(pr.oid)::text from (values ('commit_risk_free_upload'), ('record_risk_free_refresh_results'), ('resolve_risk_free_review_item'), ('correct_risk_free_observation'), ('set_risk_free_series_state')) as v(a) left join pg_proc pr on pr.proname = v.a and pr.pronamespace = 'public'::regnamespace group by a
  ) raw
),
